-- Modify "request_attempts" table
ALTER TABLE "accountdeletion"."request_attempts" DROP CONSTRAINT "request_attempts_reason_check", ADD CONSTRAINT "request_attempts_reason_check" CHECK ((char_length(reason) <= 1000) AND ((requester <> 'ADMIN'::text) OR ((char_length(reason) >= 1) AND (reason !~ '^[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]|[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]$'::text))));
